targets.expr:
sum by (k8s_pod_uid, k8s_pod_name, gpu_uuid) (
  rate(gpu_cuda_memory_allocations_bytes_total{
    k8s_pod_uid=~"$pod_uid",k8s_pod_name=~"$pod",gpu_uuid=~"$gpu_uuid"
  }[$__rate_interval])
)
/
clamp_min(
  sum by (k8s_pod_uid, k8s_pod_name, gpu_uuid) (
    rate(gpu_cuda_memory_allocations_calls_total{
      k8s_pod_uid=~"$pod_uid",k8s_pod_name=~"$pod",gpu_uuid=~"$gpu_uuid"
    }[$__rate_interval])
  ),
  1
)

sum by (k8s_pod_uid, k8s_pod_name, gpu_uuid, cuda_memcpy_kind) (
  rate(gpu_cuda_memory_copies_bytes_total_sum{
    k8s_pod_uid=~"$pod_uid",k8s_pod_name=~"$pod",gpu_uuid=~"$gpu_uuid",
    cuda_memcpy_kind=~"MemcpyDeviceToHost"
  }[$__rate_interval])
)

sum by (k8s_pod_uid, k8s_pod_name, gpu_uuid, cuda_memcpy_kind) (
  rate(gpu_cuda_memory_copies_bytes_total_sum{
    k8s_pod_uid=~"$pod_uid",k8s_pod_name=~"$pod",gpu_uuid=~"$gpu_uuid",
    cuda_memcpy_kind=~"MemcpyHostToDevice"
  }[$__rate_interval])
)

sum by (k8s_pod_uid, k8s_pod_name, gpu_uuid, cuda_function, cuda_error_code) (
  increase(gpu_cuda_errors_total{k8s_pod_uid=~"$pod_uid",k8s_pod_name=~"$pod",gpu_uuid=~"$gpu_uuid"}[$__rate_interval])
)

sum by (k8s_pod_uid, k8s_pod_name, gpu_uuid, cuda_function, hami_oom_mem_kind, hami_oom_error_code) (
  increase(gpu_hami_oom_events_total{k8s_pod_uid=~"$pod_uid",k8s_pod_name=~"$pod",gpu_uuid=~"$gpu_uuid"}[$__rate_interval])
)

max_over_time(
  sum by (k8s_pod_uid, k8s_pod_name, gpu_uuid, cuda_function, hami_oom_mem_kind, hami_oom_error_code) (
    gpu_hami_oom_events_total{k8s_pod_uid=~"$pod_uid",k8s_pod_name=~"$pod",gpu_uuid=~"$gpu_uuid"}
  )[$__range:]
)

histogram_quantile(
  0.95,
  sum by (k8s_pod_uid, k8s_pod_name, gpu_uuid, le) (
    rate(gpu_hami_compute_throttle_duration_seconds_bucket{
      k8s_pod_uid=~"$pod_uid",k8s_pod_name=~"$pod",gpu_uuid=~"$gpu_uuid"
    }[$__rate_interval])
  )
)

histogram_quantile(
  0.99,
  sum by (k8s_pod_uid, k8s_pod_name, gpu_uuid, le) (
    rate(gpu_hami_compute_throttle_duration_seconds_bucket{
      k8s_pod_uid=~"$pod_uid",k8s_pod_name=~"$pod",gpu_uuid=~"$gpu_uuid"
    }[$__rate_interval])
  )
)
